style.css:
/* =========================================
   SHIBOYGI — ULTIMATE LIVE ANIME WALLPAPER
   ========================================= */

/* ? SPEED CONTROLS (edit freely) */
:root {
    --aurora-speed: 22s;
    --petal-speed: 30s;
    --rain-speed: 18s;
    --glow-speed: 6s;
}

/* ? AURORA ANIME SKY */
html, body {
    background: linear-gradient(
        120deg,
        #7f00ff,
        #b44cff,
        #ff6ec7,
        #9f7aea,
        #5f2cff
    ) !important;
    background-size: 600% 600% !important;
    animation: shiboygiAurora var(--aurora-speed) ease infinite;
}

/* ? AUTO NIGHT MODE */
@media (prefers-color-scheme: dark) {
    body::before {
        background: rgba(5, 5, 20, 0.65);
    }
}

/* ☀️ AUTO DAY MODE */
@media (prefers-color-scheme: light) {
    body::before {
        background: rgba(255, 255, 255, 0.15);
    }
}

/* ? DEPTH OVERLAY */
body::before {
    content: "";
    position: fixed;
    inset: 0;
    z-index: -1;
    backdrop-filter: blur(2px);
}

/* ? FALLING SAKURA PETALS */
body::after {
    content: "";
    position: fixed;
    inset: 0;
    pointer-events: none;
    z-index: 1;
    background-image:
        radial-gradient(circle, rgba(255,182,193,0.9) 2px, transparent 3px),
        radial-gradient(circle, rgba(255,150,220,0.7) 1.5px, transparent 3px),
        radial-gradient(circle, rgba(255,120,200,0.6) 2.5px, transparent 4px);
    background-size: 240px 240px, 340px 340px, 280px 280px;
    animation: shiboygiPetals var(--petal-speed) linear infinite;
}

/* ? ANIME RAIN LAYER */
html::after {
    content: "";
    position: fixed;
    inset: 0;
    pointer-events: none;
    z-index: 2;
    background-image: repeating-linear-gradient(
        -15deg,
        rgba(200,150,255,0.25) 0px,
        rgba(200,150,255,0.25) 1px,
        transparent 1px,
        transparent 12px
    );
    animation: shiboygiRain var(--rain-speed) linear infinite;
}

/* ? GLOW PULSE (SYNCED) */
body {
    animation:
        shiboygiAurora var(--aurora-speed) ease infinite,
        shiboygiGlow var(--glow-speed) ease-in-out infinite;
}

/* ? ANIMATIONS */
@keyframes shiboygiAurora {
    0% { background-position: 0% 50%; }
    50% { background-position: 100% 50%; }
    100% { background-position: 0% 50%; }
}

@keyframes shiboygiPetals {
    from { background-position: 0 0, 0 0, 0 0; }
    to { background-position: 0 2400px, 0 1700px, 0 2000px; }
}

@keyframes shiboygiRain {
    from { background-position: 0 0; }
    to { background-position: 0 2000px; }
}

@keyframes shiboygiGlow {
    0%, 100% {
        filter: brightness(1) saturate(1.1);
    }
    50% {
        filter: brightness(1.25) saturate(1.4);
    }
}

/* ? GLASSMORPHISM UI */
div, section, header, nav, main, article, aside {
    backdrop-filter: blur(16px) saturate(140%);
    background: rgba(255, 255, 255, 0.09) !important;
    border-radius: 18px !important;
    box-shadow: 0 0 25px rgba(180, 120, 255, 0.35);
}

/* ? INPUTS */
input, textarea {
    background: rgba(0,0,0,0.55) !important;
    color: #ffffff !important;
    border: 1px solid rgba(255,255,255,0.3) !important;
}

/* ? LINKS */
a {
    color: #f3b1ff !important;
    text-shadow: 0 0 10px rgba(243,177,255,1);
}
